import React, { useState } from 'react';
import { StyleSheet, Pressable, View } from 'react-native';
import { Screen } from '../components/ui/Screen';
import { Text, useTheme } from 'react-native-paper';
import { setPolicyAcceptance, POLICY_VERSION } from '../lib/policy';
import { useNavigation } from '@react-navigation/native';
import { PrimaryButton } from '../components/ui/PrimaryButton';

export default function PolicyScreen() {
  const navigation = useNavigation<any>();
  const [checked, setChecked] = useState(false);
  const [saving, setSaving] = useState(false);
  const theme = useTheme();

  const handleContinue = async () => {
    setSaving(true);
    const now = new Date().toISOString();
    await setPolicyAcceptance(POLICY_VERSION, now);
    setSaving(false);
    navigation.reset({ index: 0, routes: [{ name: 'Main' }] });
  };

  const toggle = () => setChecked(prev => !prev);

  return (
    <Screen>
      <Text variant="headlineMedium" style={{ marginBottom: theme.spacing.md }}>
        Terms of Use and Privacy Policy
      </Text>
      <Text variant="bodyMedium" style={{ marginBottom: theme.spacing.lg }}>
        Track receipts and mileage locally – your data never leaves the device.
      </Text>
      <Pressable
        style={styles.checkboxRow}
        onPress={toggle}
        accessibilityRole="checkbox"
        accessibilityState={{ checked }}
        accessibilityLabel="I agree to the Terms of Use and Privacy Policy."
      >
        <Text variant="bodyLarge" style={{ marginRight: theme.spacing.sm }}>
          {checked ? '\u2611' : '\u2610'}
        </Text>
        <Text variant="bodyMedium">I agree to the Terms of Use and Privacy Policy.</Text>
      </Pressable>
      <PrimaryButton onPress={handleContinue} disabled={!checked || saving} loading={saving} style={{ marginTop: theme.spacing.lg }}>
        Continue
      </PrimaryButton>
    </Screen>
  );
}

const styles = StyleSheet.create({
  checkboxRow: { flexDirection: 'row', alignItems: 'center', marginBottom: 8 },
});"}

