import React, { useEffect, useState } from 'react';
import { Provider as PaperProvider } from 'react-native-paper';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { appTheme } from './theme';
import { SafeAreaProvider } from 'react-native-safe-area-context';
import BottomTabNavigator from './components/ui/BottomTabNavigator';
import PolicyScreen from './screens/PolicyScreen';
import * as SecureStore from 'expo-secure-store';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { Platform } from 'react-native';
import { POLICY_VERSION } from './lib/policy';

const paperSettings = {
  icon: (props: any) => <MaterialCommunityIcons {...props} aria-hidden={true} />, // eslint-disable-line react/jsx-props-no-spreading
};

const getPolicyAcceptance = async (): Promise<any> => {
  try {
    const key = 'policyAcceptance';
    if (Platform.OS === 'web') {
      const json = await AsyncStorage.getItem(key);
      return json ? JSON.parse(json) : null;
    }
    const json = await SecureStore.getItemAsync(key);
    return json ? JSON.parse(json) : null;
  } catch {
    return null;
  }
};

export default function App() {
  const [checking, setChecking] = useState(true);
  const [accepted, setAccepted] = useState(false);

  useEffect(() => {
    const init = async () => {
      const acceptance = await getPolicyAcceptance();
      if (acceptance && acceptance.version === POLICY_VERSION) {
        setAccepted(true);
      }
      setChecking(false);
    };
    init();
  }, []);

  if (checking) {
    return (
      <SafeAreaProvider>
        <PaperProvider theme={appTheme} settings={paperSettings}>
          <></>
        </PaperProvider>
      </SafeAreaProvider>
    );
  }

  return (
    <SafeAreaProvider>
      <PaperProvider theme={appTheme} settings={paperSettings}>
        {accepted ? <BottomTabNavigator /> : <PolicyScreen onAccept={() => setAccepted(true)} />}
      </PaperProvider>
    </SafeAreaProvider>
  );
}
"}

